<?php
/** Vars: $cfg $demo $error $profiles $hsProfiles $out $p $cred $log $tplFiles $tplDir $zipOk $steps */
$ico = ['ok' => 'ok', 'warn' => 'warn', 'err' => 'err', 'plan' => 'info', 'skip' => 'neutral'];
$stLabel = ['ok' => 'OK', 'warn' => 'Check', 'err' => 'Failed', 'plan' => 'Planned', 'skip' => 'Skipped'];
$info = [
    'check' => ['Connectivity check', 'Read-only: confirms NextMON can talk to the router and reports version, hotspot, API services, clock and existing NextMON users.'],
    'user' => ['Least-privilege API user', 'Creates a group with only the rights NextMON needs and a dedicated API user (docs/mikrotik-scripts/07). Better than using admin.'],
    'services' => ['API services', 'Enables the API (and optionally API-SSL with a self-signed certificate) and can limit it to the NextMON server address (docs/06).'],
    'scripts' => ['On-login and expiry scripts', 'Installs the hourly cleanup script and writes the voucher on-login script on the hotspot profiles you tick (generated by NextMON, Mikhmon compatible).'],
    'walled' => ['Walled garden defaults', 'Lets guests reach the portal, payment gateways and captive-portal checks without logging in (docs/08). Existing entries are never duplicated.'],
    'ntp' => ['Clock and NTP', 'Voucher expiry is calculated from the router clock, so NTP/SNTP must be running.'],
    'template' => ['Hotspot login template', 'RouterOS API cannot upload files, so upload the template folder yourself (WinBox, FTP or SCP), then verify it here and point the hotspot profile to it.'],
];
$f = fn(string $k) => $p[$k] ?? '';
$stepOut = fn(string $s) => ($out && $out['step'] === $s) ? $out : null;
?>
<link rel="stylesheet" href="<?= e(asset('/assets/css/mod-network.css')) ?>">
<?= page_head(t('Setup wizard'), t('Prepare a router for NextMON step by step. Every step can be previewed first: nothing is sent until you apply it.')) ?>

<div class="alert info" style="margin-bottom:var(--s4)"><?= icon('router', 18) ?><div style="flex:1">
  <?= e(t('Router')) ?>: <b><?= e($cfg['name'] ?? '-') ?></b><?= $demo ? ' (demo)' : '' ?>
  <?php if ($error) { ?><br><span class="muted"><?= e(t('Could not read the router right now: :e', [':e' => $error])) ?></span><?php } ?>
  <br><span class="muted"><?= e(t('Run this wizard with an administrator account on the router. Use "Show commands" to review, and keep a backup (Monitor > Backups) before applying.')) ?></span></div></div>

<ol class="nm-steps">
<?php foreach ($steps as $s) { $o = $stepOut($s); ?>
  <li class="nm-step" id="s-<?= $s ?>">
    <div class="nm-step-h"><h2><?= e(t($info[$s][0])) ?></h2></div>
    <div class="nm-step-b">
      <p class="muted" style="margin:0"><?= e(t($info[$s][1])) ?></p>
      <form method="post" action="<?= e(url('/wizard/run')) ?>" class="stack">
        <?= csrf_field() ?><input type="hidden" name="step" value="<?= $s ?>">

        <?php if ($s === 'user') { ?>
        <div class="form-grid">
          <div class="field"><label for="w-ip"><?= e(t('NextMON server address')) ?></label><input class="input mono" id="w-ip" name="server_ip" value="<?= e($f('server_ip')) ?>" placeholder="192.168.88.10 or 192.168.88.0/24"><p class="help"><?= e(t('Optional but recommended: the user can log in only from here.')) ?></p></div>
          <div class="field"><label for="w-user"><?= e(t('API user name')) ?></label><input class="input mono" id="w-user" name="api_user" value="<?= e($f('api_user')) ?>" maxlength="32"></div>
          <div class="field full"><label for="w-lvl"><?= e(t('Access level')) ?></label><select class="select" id="w-lvl" name="level"><option value="op"<?= sel('op', $f('level')) ?>><?= e(t('Operator (read, write, api, test, policy) - needed for vouchers and on-login scripts')) ?></option><option value="ro"<?= sel('ro', $f('level')) ?>><?= e(t('Read-only (read, api) - dashboard and monitor only')) ?></option></select></div>
        </div>
        <label class="check"><input type="checkbox" name="ack_resetuser" value="1"><?= e(t('If the user already exists, reset its password (extra confirmation)')) ?></label>
        <?php } elseif ($s === 'services') { ?>
        <div class="form-grid">
          <div class="field"><label for="w-ip2"><?= e(t('Allow API only from')) ?></label><input class="input mono" id="w-ip2" name="server_ip" value="<?= e($f('server_ip')) ?>" placeholder="192.168.88.10 or 192.168.88.0/24"><p class="help"><?= e(t('Empty = leave the allowed addresses unchanged.')) ?></p></div>
          <div class="field"><label class="check" style="margin-top:var(--s5)"><input type="checkbox" name="ssl" value="1"<?= chk($f('ssl') === '1') ?>><?= e(t('Also enable API-SSL (creates a self-signed certificate; signing can take a while)')) ?></label></div>
        </div>
        <label class="check"><input type="checkbox" name="ack_lockout" value="1"><?= e(t('I know that limiting the API to an address blocks NextMON if it connects from a different address (extra confirmation)')) ?></label>
        <?php } elseif ($s === 'scripts') { ?>
        <div class="form-grid">
          <div class="field"><label for="w-mode"><?= e(t('Mode')) ?></label><select class="select" id="w-mode" name="ol_mode"><?php foreach (['remc' => 'remc - remove on expiry and record the sale', 'rem' => 'rem - remove on expiry', 'ntfc' => 'ntfc - keep, block login, record the sale', 'ntf' => 'ntf - keep and block login', 'none' => 'none'] as $k => $l) { ?><option value="<?= $k ?>"<?= sel($k, $f('mode')) ?>><?= e($l) ?></option><?php } ?></select></div>
          <div class="field"><label class="check" style="margin-top:var(--s5)"><input type="checkbox" name="lock_user" value="1"<?= chk($f('lock_user') === '1') ?>><?= e(t('Lock the voucher to the first device (MAC)')) ?></label></div>
        </div>
        <?php if ($profiles) { ?>
        <div class="table-wrap"><table class="tbl resp">
          <thead><tr><th class="cell-chk"><span class="sr-only"><?= e(t('Select')) ?></span></th><th><?= e(t('Profile')) ?></th><th><?= e(t('Current script')) ?></th><th><?= e(t('Price')) ?></th><th><?= e(t('Validity')) ?></th></tr></thead>
          <tbody><?php foreach ($profiles as $pr) { if (in_array($pr['name'], ['default', 'default-encryption'], true)) { continue; } $m = $pr['meta']; ?>
            <tr><td class="cell-chk" data-label=""><input type="checkbox" name="profiles[]" value="<?= e($pr['name']) ?>" aria-label="<?= e($pr['name']) ?>"></td>
              <td data-label="<?= e(t('Profile')) ?>"><?= e($pr['name']) ?></td>
              <td data-label="<?= e(t('Current script')) ?>"><?= $m ? badge($m['mode'] . ' / ' . ($m['validity'] ?: '-'), 'info') : ($pr['has'] ? badge(t('other script'), 'warn') : badge(t('none'), 'neutral')) ?></td>
              <td data-label="<?= e(t('Price')) ?>"><input class="input input-sm mono" name="price[<?= e($pr['name']) ?>]" aria-label="<?= e(t('Price') . ' ' . $pr['name']) ?>" value="<?= e($m['price'] ?? '') ?>" inputmode="numeric" style="max-width:120px"></td>
              <td data-label="<?= e(t('Validity')) ?>"><input class="input input-sm mono" name="validity[<?= e($pr['name']) ?>]" aria-label="<?= e(t('Validity') . ' ' . $pr['name']) ?>" value="<?= e($m['validity'] ?? '') ?>" placeholder="1d" style="max-width:100px" autocapitalize="off"></td></tr>
          <?php } ?></tbody>
        </table></div>
        <label class="check"><input type="checkbox" name="ack_overwrite" value="1"><?= e(t('Replace on-login scripts that already exist on ticked profiles (extra confirmation)')) ?></label>
        <?php } else { ?><p class="help"><?= e(t('No profiles could be read. Only the cleanup script will be installed.')) ?></p><?php } ?>
        <?php } elseif ($s === 'walled') { ?>
        <div class="form-grid"><div class="field"><label for="w-portal"><?= e(t('NextMON portal host')) ?></label><input class="input mono" id="w-portal" name="portal" value="<?= e($f('portal')) ?>" placeholder="nextmon.example.com"><p class="help"><?= e(t('Adds this host plus Midtrans, Xendit, Tripay and captive-portal checks.')) ?></p></div></div>
        <?php } elseif ($s === 'ntp') { ?>
        <div class="form-grid">
          <div class="field"><label for="w-ntp"><?= e(t('NTP servers')) ?></label><input class="input mono" id="w-ntp" name="ntp_servers" value="<?= e($f('ntp_servers')) ?>"></div>
          <div class="field"><label for="w-tz"><?= e(t('Time zone')) ?></label><input class="input mono" id="w-tz" name="tz" value="<?= e($f('tz')) ?>" placeholder="Asia/Jakarta"><p class="help"><?= e(t('Empty = do not change.')) ?></p></div>
        </div>
        <label class="check"><input type="checkbox" name="ack_tz" value="1"><?= e(t('Allow changing the time zone (extra confirmation)')) ?></label>
        <?php } elseif ($s === 'template') { ?>
        <div class="stack">
          <?php if ($tplDir) { ?>
          <div><b><?= e(t('Files to upload')) ?></b> <span class="muted">(<?= count($tplFiles) ?>)</span>
            <div class="nm-pre" tabindex="0" style="max-height:140px"><?= e(implode("\n", array_keys($tplFiles))) ?></div>
            <?php if ($zipOk) { ?><a class="btn btn-sm" style="margin-top:var(--s2)" href="<?= e(url('/wizard/template.zip')) ?>"><?= icon('download', 16) ?><?= e(t('Download hotspot-nextmon.zip')) ?></a><?php } ?></div>
          <?php } else { ?><p class="help"><?= e(t('The shared/hotspot-login folder was not found next to this installation.')) ?></p><?php } ?>
          <div><b><?= e(t('Upload options (pick one)')) ?></b>
            <pre class="nm-pre" tabindex="0">WinBox:  Files &gt; drag the hotspot-nextmon folder in
FTP:     /ip service enable ftp   (disable it again afterwards)
         ftp &lt;router-ip&gt;; mkdir hotspot-nextmon; cd hotspot-nextmon; put login.html ... (keep css/ js/ img/)
SCP:     scp -r hotspot-nextmon admin@&lt;router-ip&gt;:/
Flash:   routers with a flash folder: use flash/hotspot-nextmon</pre></div>
          <div class="form-grid">
            <div class="field"><label for="w-dir"><?= e(t('Folder on the router')) ?></label><input class="input mono" id="w-dir" name="html_dir" value="<?= e($f('html_dir')) ?>"></div>
            <div class="field"><label for="w-hsp"><?= e(t('Hotspot profile to switch (optional)')) ?></label><select class="select" id="w-hsp" name="hs_profile"><option value=""><?= e(t('(only verify the upload)')) ?></option><?php foreach ($hsProfiles as $h) { ?><option<?= sel($h, $f('hs_profile')) ?>><?= e($h) ?></option><?php } ?></select></div>
          </div>
          <label class="check"><input type="checkbox" name="ack_htmldir" value="1"><?= e(t('Switch the live login page of that profile (extra confirmation)')) ?></label>
        </div>
        <?php } ?>

        <div class="row" style="flex-wrap:wrap">
          <button class="btn" name="mode" value="preview"><?= icon('terminal', 16) ?><?= e(t('Show commands')) ?></button>
          <?php if ($s === 'check') { ?>
          <button class="btn btn-primary" name="mode" value="apply"><?= icon('check', 16) ?><?= e(t('Run check')) ?></button>
          <?php } else { ?>
          <label class="check"><input type="checkbox" name="confirm" value="1"><?= e(t('I reviewed the commands and want to apply them')) ?></label>
          <button class="btn btn-primary" name="mode" value="apply"><?= icon('check', 16) ?><?= e(t('Apply')) ?></button>
          <?php } ?>
        </div>
      </form>

      <?php if ($s === 'user' && $cred) { ?>
      <div class="alert warn"><?= icon('key', 18) ?><div style="flex:1"><?= e(t('A new password was generated for user :u. NextMON can store it for this router, so you never need to see it.', [':u' => $cred['user']])) ?></div>
        <form method="post" action="<?= e(url('/wizard/use-user')) ?>"><?= csrf_field() ?><input type="hidden" name="confirm" value="1"><button class="btn btn-sm" data-confirm="<?= e(t('Switch NextMON to the new API user for this router?')) ?>"><?= e(t('Use this user in NextMON')) ?></button></form></div>
      <?php } ?>

      <?php if ($o) { ?>
      <div class="nm-log" role="status" aria-live="polite">
        <div><b><?= e($o['mode'] === 'apply' ? t('Result') : t('Commands that would run (nothing was sent)')) ?></b></div>
        <?php foreach ($o['rows'] as $r) { ?>
        <div style="flex-wrap:wrap"><?= badge(t($stLabel[$r['status']] ?? $r['status']), $ico[$r['status']] ?? 'neutral') ?> <b><?= e($r['label']) ?></b>
          <?php if ($r['msg'] !== '') { ?><span class="muted"><?= e($r['msg']) ?></span><?php } ?></div>
        <div style="padding-left:var(--s4)"><code class="mono muted" style="font-size:var(--fs-12);overflow-wrap:anywhere"><?= e($r['cli']) ?></code></div>
        <?php if ($r['detail'] !== '') { ?><details style="padding-left:var(--s4)"><summary class="muted"><?= e(t('Show script')) ?></summary><pre class="nm-pre" tabindex="0"><?= e($r['detail']) ?></pre></details><?php } ?>
        <?php } ?>
      </div>
      <?php } ?>
    </div>
  </li>
<?php } ?>
</ol>

<section class="card glass" style="margin-top:var(--s5)">
  <div class="card-h"><h2><?= e(t('Applied commands log')) ?></h2></div>
  <?php if (!$log) { echo empty_state('terminal', t('Nothing applied yet')); } else { ?>
  <div class="table-wrap" style="max-height:420px"><table class="tbl resp">
    <thead><tr><th><?= e(t('Time')) ?></th><th><?= e(t('Step')) ?></th><th><?= e(t('Command')) ?></th><th><?= e(t('Result')) ?></th></tr></thead>
    <tbody><?php foreach ($log as $l) { ?>
      <tr><td data-label="<?= e(t('Time')) ?>" class="mono nowrap"><?= e(date('m-d H:i:s', (int)$l['ts'])) ?></td><td data-label="<?= e(t('Step')) ?>"><?= e($l['step']) ?></td>
        <td data-label="<?= e(t('Command')) ?>" class="wrap mono" style="font-size:var(--fs-12)"><?= e($l['label']) ?><br><span class="muted"><?= e($l['cli']) ?></span></td>
        <td data-label="<?= e(t('Result')) ?>" class="wrap"><?= badge(t($stLabel[$l['status']] ?? $l['status']), $ico[$l['status']] ?? 'neutral') ?> <span class="muted"><?= e($l['msg']) ?></span></td></tr>
    <?php } ?></tbody>
  </table></div>
  <?php } ?>
</section>
